import React, { useState } from "react";

function App() {
  const [formData, setFormData] = useState({
    nombre: "",
    email: "",
    telefono: "",
    edad: "",
    ocupacion: "",
    cursoId: ""
  });

  // Manejar cambios en los inputs
  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  // Enviar los datos al backend
  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const response = await fetch("http://localhost:3001/api/usuarios/inscribirse", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify(formData)
      });

      const data = await response.json();

      if (response.ok) {
        alert("¡Inscripción exitosa!");
        console.log(data);
      } else {
        alert("Error en la inscripción");
        console.error(data);
      }
    } catch (error) {
      console.error("Error al conectar con el servidor:", error);
    }
  };

  return (
    <div>
      <h2>Inscribirse en un curso</h2>
      <form onSubmit={handleSubmit}>
        <input type="text" name="nombre" placeholder="Nombre" onChange={handleChange} required />
        <input type="email" name="email" placeholder="Email" onChange={handleChange} required />
        <input type="text" name="telefono" placeholder="Teléfono" onChange={handleChange} required />
        <input type="number" name="edad" placeholder="Edad" onChange={handleChange} required />
        <input type="text" name="ocupacion" placeholder="Ocupación" onChange={handleChange} required />
        <input type="number" name="cursoId" placeholder="ID del curso" onChange={handleChange} required />
        <button type="submit">Inscribirse</button>
      </form>
    </div>
  );
}

export default App;
